-- ═══════════════════════════════════════════════════════════════
--  OG Jobs · Seed dữ liệu nền (countries / companies / skills / fx_rates)
--
--  File này TƯƠNG ĐƯƠNG apps/api/src/scripts/seed.ts, viết bằng SQL thuần
--  để dùng khi trên máy KHÔNG có Node/pnpm: dán thẳng vào SQL Editor của
--  Neon / Supabase, hoặc chạy `psql -f seed.sql`.
--
--  ⚠️ Phải chạy SAU khi migration đã tạo bảng (API khởi động lần đầu sẽ
--     tự chạy `prisma migrate deploy`).
--  ✅ Chạy lại nhiều lần vẫn an toàn — mọi câu đều có ON CONFLICT.
-- ═══════════════════════════════════════════════════════════════

BEGIN;

-- ─────────── countries (49) ───────────

-- ─────────── companies (38) ───────────

-- ─────────── skills (32) ───────────

-- ─────────── fx_rates (47) — tỉ giá dự phòng, cron sẽ ghi đè bằng số thật ───────────

COMMIT;

-- ─────────── Kiểm chứng ───────────
SELECT 'countries' AS bang, COUNT(*) AS so_dong FROM countries
UNION ALL SELECT 'companies', COUNT(*) FROM companies
UNION ALL SELECT 'skills',    COUNT(*) FROM skills
UNION ALL SELECT 'fx_rates',  COUNT(*) FROM fx_rates;
